/* ============================================================
   terrain.js — Historically-inspired terrain of Imperial Rome
   - The 7 hills (Palatine, Capitoline, Quirinal, Viminal,
     Esquiline, Caelian, Aventine)
   - The Tiber River with its great meander enclosing
     Campus Martius, plus the river bed depression
   - Flattened Forum valley (Cloaca Maxima drainage) and
     Circus Maximus valley
   Also provides the shared build helpers used by all modules.
   ============================================================ */
window.ROME = (function () {
  'use strict';

  /* ---- The seven hills (x = east, z = south, metres) ---- */
  const HILLS = [
    { name: 'Palatine',  x:  120, z:  200, h: 40, r: 250 },
    { name: 'Capitoline',x:  -90, z:  140, h: 38, r: 200 },
    { name: 'Quirinal',  x:  140, z: -560, h: 30, r: 260 },
    { name: 'Viminal',   x: -140, z: -430, h: 24, r: 210 },
    { name: 'Esquiline', x:  620, z: -200, h: 44, r: 380 },
    { name: 'Caelian',   x:  430, z:  460, h: 40, r: 300 },
    { name: 'Aventine',  x:  180, z:  720, h: 32, r: 270 }
  ];

  /* ---- Tiber: great meander around Campus Martius ---- */
  function riverXAt(z) {
    // Runs roughly N-S, swings far west around z=-300 (Campus Martius)
    return 110 - 640 * Math.exp(-((z + 300) * (z + 300)) / (2 * 430 * 430));
  }

  const RIVER_HALF_W = 34;      // half width of the water channel
  const RIVER_BED_Y  = -6.5;    // water surface height

  /* smooth flat patches (drained valley floors, lowlands) */
  const FLATS = [
    { x:   20, z:  190, r: 210, t:  9 },   // Roman Forum valley
    { x:  210, z:  460, r: 170, t:  5 },   // Circus Maximus valley
    { x: -460, z:   60, r: 300, t:  4 },   // Campus Martius lowland
    { x: -300, z:  -420, r: 180, t:  5 }   // Forum Boarium / Field of Mars
  ];

  function smoothstep(a, b, x) {
    const t = Math.max(0, Math.min(1, (x - a) / (b - a)));
    return t * t * (3 - 2 * t);
  }

  /* ---- terrain height field ---- */
  function heightAt(x, z) {
    let h = 0;
    for (let i = 0; i < HILLS.length; i++) {
      const hi = HILLS[i];
      const dx = x - hi.x, dz = z - hi.z;
      h += hi.h * Math.exp(-(dx * dx + dz * dz) / (2 * hi.r * hi.r));
    }
    // gentle rolling countryside for the far fields
    h += 2.2 * Math.sin(x * 0.008) * Math.cos(z * 0.011);
    // Tiber bed
    const d = x - riverXAt(z);
    h -= 14 * Math.exp(-(d * d) / (2 * 55 * 55));
    // drained flat areas
    for (let i = 0; i < FLATS.length; i++) {
      const f = FLATS[i];
      const dist = Math.hypot(x - f.x, z - f.z);
      const w = 1 - smoothstep(f.r * 0.45, f.r, dist);
      if (w > 0) h = h + (f.t - h) * w;
    }
    return h;
  }

  /* ---- shared materials ---- */
  const M = {
    stone:      new THREE.MeshLambertMaterial({ color: 0xb8ae9c }),
    travertine: new THREE.MeshLambertMaterial({ color: 0xd8c9a3 }),
    marble:     new THREE.MeshLambertMaterial({ color: 0xe9e6dc }),
    brick:      new THREE.MeshLambertMaterial({ color: 0x9c5b41 }),
    tuff:       new THREE.MeshLambertMaterial({ color: 0xbfa87e }),
    terracotta: new THREE.MeshLambertMaterial({ color: 0xb05a3c }),
    wood:       new THREE.MeshLambertMaterial({ color: 0x7a5b3a }),
    sand:       new THREE.MeshLambertMaterial({ color: 0xcdbb92 }),
    water:      new THREE.MeshLambertMaterial({ color: 0x2f6f9e, transparent: true, opacity: 0.88 }),
    gold:       new THREE.MeshLambertMaterial({ color: 0xd9a832 }),
    bronze:     new THREE.MeshLambertMaterial({ color: 0x8a6d3b }),
    dark:       new THREE.MeshLambertMaterial({ color: 0x6e6252 }),
    fresco:     new THREE.MeshLambertMaterial({ color: 0xd77a52 }),
    green:      new THREE.MeshLambertMaterial({ color: 0x4a6b3a })
  };

  /* ---- tiny geometry helpers (y = BOTTOM of object, absolute) ---- */
  function box(w, h, d, mat, x, y, z, ry) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
    m.position.set(x, y + h / 2, z);
    if (ry) m.rotation.y = ry;
    m.castShadow = m.receiveShadow = true;
    return m;
  }
  function cyl(rt, rb, h, seg, mat, x, y, z) {
    const m = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, seg), mat);
    m.position.set(x, y + h / 2, z);
    m.castShadow = m.receiveShadow = true;
    return m;
  }
  /* cypress / olive tree */
  function tree(x, z, s) {
    const g = new THREE.Group();
    const ground = heightAt(x, z);
    g.add(cyl(0.3 * s, 0.4 * s, 2.2 * s, 6, M.wood, 0, 0, 0));
    const c = new THREE.Mesh(new THREE.ConeGeometry(1.4 * s, 5.5 * s, 8), M.green);
    c.position.set(0, 2.2 * s + 2.6 * s, 0);
    c.castShadow = true;
    g.add(c);
    g.position.set(x, ground, z);
    return g;
  }
  function column(x, z, r, h, mat) {
    const g = new THREE.Group();
    const ground = heightAt(x, z);
    g.add(cyl(r * 1.3, r * 1.5, h * 0.08, 12, mat || M.marble, 0, 0, 0)); // base
    g.add(cyl(r, r * 1.05, h * 0.88, 12, mat || M.marble, 0, h * 0.06, 0)); // shaft
    g.add(cyl(r * 1.4, r * 1.1, h * 0.08, 12, mat || M.marble, 0, h * 0.94, 0)); // capital
    g.position.set(x, ground, z);
    return g;
  }

  /* ---- terrain mesh with vertex colours ---- */
  function buildTerrain(scene) {
    const SIZE = 3400, SEGS = 170;
    const geo = new THREE.PlaneGeometry(SIZE, SIZE, SEGS, SEGS);
    geo.rotateX(-Math.PI / 2);
    const pos = geo.attributes.position;
    const colors = [];
    const cSand = new THREE.Color(0xbfb28c);
    const cGrass = new THREE.Color(0x7d8a4f);
    const cDry = new THREE.Color(0x9d9763);
    const cRock = new THREE.Color(0x8d8578);
    const tmp = new THREE.Color();
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i), z = pos.getZ(i);
      const y = heightAt(x, z);
      pos.setY(i, y);
      if (y < 1.5) tmp.copy(cSand);
      else if (y < 12) tmp.copy(cGrass).lerp(cDry, (y - 1.5) / 10.5);
      else tmp.copy(cDry).lerp(cRock, Math.min(1, (y - 12) / 28));
      colors.push(tmp.r, tmp.g, tmp.b);
    }
    geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
    geo.computeVertexNormals();
    const mat = new THREE.MeshLambertMaterial({ vertexColors: true });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.receiveShadow = true;
    scene.add(mesh);
  }

  /* ---- Tiber ribbon ---- */
  function buildRiver(scene) {
    const pts = [];
    for (let z = -1700; z <= 1700; z += 20) pts.push(riverXAt(z));
    const pos = [], idx = [], count = pts.length;
    for (let i = 0; i < count; i++) {
      const cx = pts[i];
      pos.push(cx - RIVER_HALF_W, RIVER_BED_Y, -1700 + i * 20);
      pos.push(cx + RIVER_HALF_W, RIVER_BED_Y, -1700 + i * 20);
    }
    for (let i = 0; i < count - 1; i++) {
      const a = i * 2, b = i * 2 + 1, c = i * 2 + 2, d = i * 2 + 3;
      idx.push(a, c, b, b, c, d);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setIndex(idx);
    geo.computeVertexNormals();
    const river = new THREE.Mesh(geo, M.water);
    scene.add(river);

    // Isola Tiberina (small island in the meander, near the Forum)
    const island = cyl(18, 26, 6, 12, M.sand, riverXAt(-140), RIVER_BED_Y - 6, -140);
    island.scale.set(1.9, 1, 1);
    scene.add(island);
  }

  return {
    HILLS: HILLS,
    heightAt: heightAt,
    riverXAt: riverXAt,
    RIVER_BED_Y: RIVER_BED_Y,
    M: M,
    box: box, cyl: cyl, tree: tree, column: column,
    buildTerrain: buildTerrain,
    buildRiver: buildRiver
  };
})();

/* ============================================================
   roads.js — The consular roads and city streets of Rome
   Via Appia (S), Via Flaminia (N), Via Latrina (E),
   Via Sacra (Forum), bridges over the Tiber
   ============================================================ */
window.RomeRoads = (function () {
  'use strict';

  /* ribbon road that follows the terrain */
  function makeRoad(scene, pts, width, mat) {
    const pos = [], idx = [];
    for (let i = 0; i < pts.length; i++) {
      const [x, z] = pts[i];
      // tangent
      const a = pts[Math.max(0, i - 1)], b = pts[Math.min(pts.length - 1, i + 1)];
      const tx = b[0] - a[0], tz = b[1] - a[1];
      const len = Math.hypot(tx, tz) || 1;
      const nx = -tz / len, nz = tx / len;
      const y = ROME.heightAt(x, z) + 0.25;
      pos.push(x + nx * width / 2, y, z + nz * width / 2);
      pos.push(x - nx * width / 2, y, z - nz * width / 2);
    }
    for (let i = 0; i < pts.length - 1; i++) {
      const a = i * 2, b = i * 2 + 1, c = i * 2 + 2, d = i * 2 + 3;
      idx.push(a, c, b, b, c, d);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setIndex(idx);
    geo.computeVertexNormals();
    const m = new THREE.Mesh(geo, mat || ROME.M.sand);
    m.receiveShadow = true;
    scene.add(m);
  }

  function line(x0, z0, x1, z1, n) {
    const pts = [];
    for (let i = 0; i <= n; i++) {
      pts.push([x0 + (x1 - x0) * i / n, z0 + (z1 - z0) * i / n]);
    }
    return pts;
  }

  /* stone bridge across the Tiber at given z */
  function bridge(scene, z, y) {
    const cx = ROME.riverXAt(z);
    const span = 110;
    const gy = ROME.RIVER_BED_Y - 1;
    const deckY = (y !== undefined) ? y : gy + 9;
    const g = new THREE.Group();
    g.add(ROME.box(span, 2.5, 12, ROME.M.travertine, cx, deckY, z));              // deck
    g.add(ROME.box(span, 1.2, 1.2, ROME.M.stone, cx, deckY + 2.5, z - 5.2));     // rail
    g.add(ROME.box(span, 1.2, 1.2, ROME.M.stone, cx, deckY + 2.5, z + 5.2));     // rail
    for (let i = -1; i <= 1; i++) {                                              // piers
      g.add(ROME.box(7, deckY - gy + 2, 10, ROME.M.stone, cx + i * span / 2.6, gy, z));
    }
    scene.add(g);
  }

  function buildRoads(scene) {
    const M = ROME.M;
    /* --- consular roads (sampled for terrain following) --- */
    // Via Appia — Forum to Porta San Sebastiano (south)
    makeRoad(scene, line(30, 260, 60, 1160, 20), 14);
    // Via Flaminia — Forum to Porta Flaminia (north)
    makeRoad(scene, line(30, 260, 60, -1330, 24), 14);
    // Via Latina / Labicana — Colosseum to Porta Tiburtina (east)
    makeRoad(scene, line(470, 200, 1180, 40, 20), 12);
    // Via Ostiensis — from Porta San Paolo (south-west)
    makeRoad(scene, line(-500, 1050, -700, 1500, 10), 12);
    // Via Aurelia — Campus Martius to the west
    makeRoad(scene, line(-500, 300, -1300, 250, 10), 12);
    // Via Sacra — the sacred processional road through the Forum
    makeRoad(scene, line(15, 290, -40, 40, 8), 10, M.marble);

    /* --- forum pavement --- */
    const fy = ROME.heightAt(20, 190) + 0.2;
    const plaza = ROME.box(230, 0.3, 300, M.sand, 20, fy, 190);
    plaza.rotation.y = 0.18;
    scene.add(plaza);

    /* --- bridges over the Tiber --- */
    bridge(scene, -300);    // Ponte Fabricio, Campus Martius meander
    bridge(scene, -1300);   // north crossing on the Flaminia
    bridge(scene, 700);     // Ponte Cestius, on the Appia
  }

  return { buildRoads: buildRoads, makeRoad: makeRoad };
})();

/* ============================================================
   walls_gates.js — The Aurelian Walls (271–275 CE)
   Brick-faced concrete circuit with square towers every ~30 m
   and the great consular gateways.
   ============================================================ */
window.RomeWalls = (function () {
  'use strict';

  const CX = 60, CZ = -80;          // circuit centre
  const RX = 1150, RZ = 1250;       // east-west / north-south radii
  const WALL_H = 14;                // raised to 35 ft by Stilicho

  function pointOnWall(t) {
    return [CX + RX * Math.cos(t), CZ + RZ * Math.sin(t)];
  }

  /* the 18 portals — a representative selection on their roads */
  const GATES = [
    { name: 'Porta San Sebastiano',  t: Math.PI / 2 },        // south  — Via Appia
    { name: 'Porta San Paolo',      t: 2.35 },               // S-W    — Via Ostiensis
    { name: 'Porta San Pancrazio',  t: Math.PI },            // west
    { name: 'Porta Flaminia',       t: -Math.PI / 2 },       // north  — Via Flaminia
    { name: 'Porta Maggiore',       t: -Math.PI / 4 - 0.25 },// N-E
    { name: 'Porta Tiburtina',      t: 0.05 },               // east   — Via Latina
    { name: 'Porta Asinaria',       t: 0.85 },               // S-E
    { name: 'Porta Latina',         t: 1.55 }                // S-S-E
  ];

  function buildGate(scene, gate) {
    const [x, z] = pointOnWall(gate.t);
    // tangent direction of the ellipse
    const tx = -RX * Math.sin(gate.t), tz = RZ * Math.cos(gate.t);
    const ry = -Math.atan2(tz, tx) + Math.PI / 2;
    const gy = ROME.heightAt(x, z);
    const g = new THREE.Group();
    const M = ROME.M;
    g.add(ROME.box(11, WALL_H + 5, 11, M.brick, 0, 0, -11));     // left tower
    g.add(ROME.box(11, WALL_H + 5, 11, M.brick, 0, 0, 11));      // right tower
    g.add(ROME.box(26, WALL_H, 7, M.brick, 0, 0, 0));            // arch body
    g.add(ROME.box(28, 3, 9, M.travertine, 0, WALL_H, 0));       // cornice
    g.add(ROME.box(28, 2, 1, M.travertine, 0, WALL_H + 3, 0));
    // arch voussoirs hint
    g.add(ROME.box(24, 5, 8.5, M.travertine, 0, 9, 0));
    g.position.set(x, gy, z);
    g.rotation.y = ry;
    scene.add(g);
  }

  function buildWallsGates(scene) {
    const M = ROME.M;
    const N = 240;
    const step = (Math.PI * 2) / N;
    const gateGap = 0.012;   // radians of gap around each gate

    for (let i = 0; i < N; i++) {
      const t = i * step;
      // skip wall segments under a gate
      let near = false;
      for (const g of GATES) {
        let d = Math.abs(((t - g.t) % (Math.PI * 2) + Math.PI * 2) % (Math.PI * 2) - Math.PI * 2 / 2);
        if (d < gateGap) { near = true; break; }
      }
      if (near) continue;

      const [x, z] = pointOnWall(t);
      const tx = -RX * Math.sin(t), tz = RZ * Math.cos(t);
      const len = Math.hypot(tx, tz) * step * RX * RZ / (Math.hypot(tx, tz)) * 0 + 0; // (unused)
      const seg = Math.hypot(tx, tz) * step;
      const ry = -Math.atan2(tz, tx);
      const gy = ROME.heightAt(x, z);
      const wall = ROME.box(13, WALL_H, 3.6, M.brick, x, gy, z, ry + Math.PI / 2);
      scene.add(wall);

      // square defensive towers ~ every 30 m (every 5th segment)
      if (i % 5 === 0) {
        const tower = ROME.box(9, WALL_H + 4, 9, M.brick,
          x + Math.cos(ry) * 6, gy, z + Math.sin(ry) * 6, ry);
        scene.add(tower);
      }
    }
    for (const g of GATES) buildGate(scene, g);
  }

  return { buildWallsGates: buildWallsGates };
})();

/* ============================================================
   temples.js — The temples of Imperial Rome
   High podium, single front stair, deep colonnaded pronaos,
   closed cella, engaged side columns — and the Pantheon
   with its unreinforced concrete dome and oculus.
   ============================================================ */
window.RomeTemples = (function () {
  'use strict';

  /* generic Roman temple on a high podium, facing +z (front) */
  function temple(scene, x, z, w, d, cols, h, ry, ruined) {
    const M = ROME.M;
    const g = new THREE.Group();
    const gy = ROME.heightAt(x, z);
    const podiumH = 3.2;
    // podium
    g.add(ROME.box(w, podiumH, d, M.travertine, 0, 0, 0));
    // front staircase (single central entry)
    g.add(ROME.box(w * 0.5, podiumH, 6, M.travertine, 0, 0, d / 2 + 3));
    for (let i = 0; i < 4; i++)
      g.add(ROME.box(w * 0.5 - i * 0.4, 0.35, 0.9, M.travertine, 0, 0.15 + i * 0.78, d / 2 + 5.4 - i * 1.45));
    // cella (closed inner room)
    g.add(ROME.box(w * 0.62, h * 0.62, d * 0.72, M.stone, 0, podiumH, -d * 0.12));
    // roof over cella
    g.add(ROME.box(w * 0.7, 1, d * 0.78, M.terracotta, 0, podiumH + h * 0.62, -d * 0.12));
    // pronaos columns (free-standing)
    const colH = h * 0.62;
    for (let i = 0; i < cols; i++) {
      const cx = -w * 0.42 + (w * 0.84) * i / (cols - 1);
      g.add(ROME.cyl(0.55, 0.65, colH, 12, M.marble, cx, podiumH, d * 0.32));
    }
    // architrave + pediment on the front
    g.add(ROME.box(w * 0.95, 1.2, 1.4, M.marble, 0, podiumH + colH, d * 0.32));
    const ped = new THREE.Mesh(new THREE.CylinderGeometry(w * 0.48, w * 0.48, 1.4, 3, 1, false, 0, Math.PI), M.marble);
    ped.rotation.set(Math.PI / 2, 0, 0);
    ped.scale.z = 0.55;
    ped.position.set(0, podiumH + colH + 1.2, d * 0.32);
    ped.castShadow = true;
    g.add(ped);
    // engaged half-columns on the sides and back
    const sideN = Math.max(3, cols);
    for (let i = 1; i < sideN; i++) {
      const sz = -d * 0.35 + (d * 0.65) * i / (sideN - 1);
      g.add(ROME.cyl(0.4, 0.5, colH, 8, M.stone, -w * 0.49, podiumH, sz));
      g.add(ROME.cyl(0.4, 0.5, colH, 8, M.stone, w * 0.49, podiumH, sz));
    }
    if (ruined) { // a few leaning, fallen columns (Temple of Saturn look)
      g.children.forEach(c => { if (Math.random() < 0.25) { c.rotation.z = (Math.random() - 0.5) * 0.25; c.position.y += 0.2; } });
    }
    g.position.set(x, gy, z);
    g.rotation.y = ry || 0;
    scene.add(g);
  }

  /* the Pantheon — rotunda, unreinforced dome, oculus, portico */
  function pantheon(scene, x, z) {
    const M = ROME.M;
    const gy = ROME.heightAt(x, z);
    const g = new THREE.Group();
    const R = 30, WALL = 16;
    // drum
    g.add(ROME.cyl(R, R, WALL, 40, M.brick, 0, 0, 0));
    g.add(ROME.box(R * 2.4, 1.4, R * 2.4, M.travertine, 0, 14.5, 0)); // cornice ring
    // concrete dome
    const dome = new THREE.Mesh(new THREE.SphereGeometry(R, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2), M.stone);
    dome.position.y = WALL; dome.scale.y = 1.05; dome.castShadow = true;
    g.add(dome);
    // oculus
    const oculus = new THREE.Mesh(new THREE.CylinderGeometry(6, 6, 3, 24, 1, true), M.dark);
    oculus.position.y = WALL + R * 1.02;
    g.add(oculus);
    const sun = new THREE.Mesh(new THREE.CircleGeometry(5.5, 24), M.gold);
    sun.rotation.x = -Math.PI / 2;
    sun.position.y = WALL + R * 1.06;
    g.add(sun);
    // portico: steps + 8 columns + pediment
    for (let i = 0; i < 5; i++)
      g.add(ROME.box(26 - i * 0.8, 0.5, 3, M.travertine, 0, i * 0.5, R + 4 + (4 - i) * 2.4));
    const base = 2.5;
    for (let i = 0; i < 8; i++) {
      const cx = -19 + (38) * i / 7;
      g.add(ROME.cyl(0.9, 1.05, 12, 14, M.marble, cx, base, R + 2.5));
    }
    g.add(ROME.box(28, 2.2, 3, M.travertine, 0, base + 12, R + 2.5));
    const ped = new THREE.Mesh(new THREE.ConeGeometry(16, 7, 4), M.terracotta);
    ped.position.set(0, base + 15.5, R + 2.5);
    ped.rotation.y = Math.PI / 4;
    ped.scale.z = 0.45;
    ped.castShadow = true;
    g.add(ped);
    g.position.set(x, gy, z);
    scene.add(g);
  }

  /* small circular shrine (Temple of Vesta) */
  function shrine(scene, x, z, r, h) {
    const M = ROME.M;
    const gy = ROME.heightAt(x, z);
    const g = new THREE.Group();
    g.add(ROME.cyl(r * 1.4, r * 1.5, 0.8, 20, M.travertine, 0, 0, 0));
    g.add(ROME.cyl(r, r, h, 20, M.stone, 0, 0.8, 0));
    const roof = new THREE.Mesh(new THREE.ConeGeometry(r + 1.5, h * 0.7, 20), M.terracotta);
    roof.position.y = 0.8 + h + h * 0.35; roof.castShadow = true;
    g.add(roof);
    const flame = new THREE.Mesh(new THREE.SphereGeometry(0.8, 8, 8), M.gold);
    flame.position.y = 0.8 + h * 0.5;
    g.add(flame); // the eternal flame
    for (let i = 0; i < 6; i++) {
      const a = i / 6 * Math.PI * 2;
      g.add(ROME.cyl(0.35, 0.4, h + 1, 10, M.marble, Math.cos(a) * (r + 2), 0.8, Math.sin(a) * (r + 2)));
    }
    g.position.set(x, gy, z);
    scene.add(g);
  }

  function buildTemples(scene) {
    // Temple of Jupiter Optimus Maximus — top of the Capitoline
    temple(scene, -90, 120, 40, 46, 6, 16, -0.5, false);
    // Temple of Saturn — Forum (state treasury), partially ruined
    temple(scene, -25, 265, 26, 30, 6, 11, 0.18, true);
    // Temple of Portunus — Forum Boarium by the river (Ionic, high podium)
    temple(scene, -330, 400, 22, 26, 4, 10, 1.2, false);
    // Temple of Venus and Roma — Hadrian's great twin temple, E of Forum
    temple(scene, 480, 330, 70, 55, 8, 20, 2.6, false);
    // Temple of Serapis — Quirinal
    temple(scene, 130, -580, 30, 36, 6, 13, 0.4, false);
    // Temple of Vesta — the round shrine of the eternal flame
    shrine(scene, 20, 150, 7, 8);
    // The Pantheon — Campus Martius, dome for all the gods
    pantheon(scene, -430, -260);
  }

  return { buildTemples: buildTemples };
})();

/* ============================================================
   colosseum.js — The Flavian Amphitheatre (70–80 CE)
   Four tiers of travertine, arched facade, east-west oval
   east of the Forum, near the Caelian and Esquiline.
   ============================================================ */
window.RomeColosseum = (function () {
  'use strict';

  /* vertical elliptical wall band between heights y0..y1 */
  function ring(scene, cx, cz, rx, rz, y0, y1, n, mat) {
    const pos = [], idx = [];
    for (let i = 0; i < n; i++) {
      const a0 = (i / n) * Math.PI * 2, a1 = ((i + 1) / n) * Math.PI * 2;
      const x0 = cx + Math.cos(a0) * rx, z0 = cz + Math.sin(a0) * rz;
      const x1 = cx + Math.cos(a1) * rx, z1 = cz + Math.sin(a1) * rz;
      pos.push(x0, y0, z0, x1, y0, z1, x1, y1, z1, x0, y1, z0);
      const a = i * 4;
      idx.push(a, a + 1, a + 3, a, a + 3, a + 2);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setIndex(idx);
    geo.computeVertexNormals();
    const m = new THREE.Mesh(geo, mat);
    m.castShadow = m.receiveShadow = true;
    scene.add(m);
  }

  /* a row of arched facade hints: alternating piers + openings */
  function arcades(scene, cx, cz, rx, rz, y, n, archH) {
    const M = ROME.M;
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2;
      const x = cx + Math.cos(a) * rx, z = cz + Math.sin(a) * rz;
      const ry = -a - Math.PI / 2;
      scene.add(ROME.box(1.6, archH, 1.6, M.stone, x, y, z, ry));
      // arch top
      const arc = new THREE.Mesh(new THREE.TorusGeometry(1.9, 0.5, 6, 10, Math.PI), M.travertine);
      arc.position.set(x, y + archH, z);
      arc.rotation.set(0, ry, 0);
      arc.castShadow = true;
      scene.add(arc);
    }
  }

  function buildColosseum(scene) {
    const M = ROME.M;
    const cx = 430, cz = 180;
    const gy = ROME.heightAt(cx, cz);
    const RX = 78, RZ = 56;

    // Tier 1: ground arcade (taller, open colonnade)
    ring(scene, cx, cz, RX, RZ, 0, 10, 64, M.travertine);
    // entablature 1
    ring(scene, cx, cz, RX + 1.5, RZ + 1.5, 10, 12.5, 64, M.stone);
    // Tier 2: semicircular arcades
    ring(scene, cx, cz, RX - 1, RZ - 1, 12.5, 21, 64, M.travertine);
    ring(scene, cx, cz, RX + 1, RZ + 1, 21, 23, 64, M.stone);
    // Tier 3: windowed order
    ring(scene, cx, cz, RX - 2.5, RZ - 2.5, 23, 31.5, 64, M.stone);
    ring(scene, cx, cz, RX - 1, RZ - 1, 31.5, 33.5, 64, M.travertine);
    // top (attic, partly lost to history)
    ring(scene, cx, cz, RX - 6, RZ - 6, 33.5, 38, 64, M.brick);

    // arcades on the tiers
    arcades(scene, cx, cz, RX + 0.2, RZ + 0.2, 0, 40, 9);
    arcades(scene, cx, cz, RX + 0.8, RZ + 0.8, 13, 34, 7.5);

    // the four corner pendentive towers
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * Math.PI * 2 + Math.PI / 4;
      const x = cx + Math.cos(a) * RX * 0.99, z = cz + Math.sin(a) * RZ * 0.99;
      const tower = ROME.box(12, 46, 12, M.travertine, x, 0, z, -a);
      tower.position.y = gy;
      scene.add(tower);
    }

    // arena floor visible from the inside
    const arena = new THREE.Mesh(new THREE.CircleGeometry(52, 40), M.sand);
    arena.rotation.x = -Math.PI / 2;
    arena.scale.set(1.3, 1, 1);
    arena.position.set(cx, gy + 0.5, cz);
    scene.add(arena);

    // base ring hugging the terrain
    ring(scene, cx, cz, RX + 3, RZ + 3, -3, 0.5, 64, M.stone);

    // shift whole structure to terrain height
    // (rings were built in absolute y — raise them all by gy)
  }

  return { buildColosseum: buildColosseum };
})();

/* ============================================================
   colosseum.js — The Flavian Amphitheatre (70–80 CE)
   Four tiers of travertine, arched facade, east-west oval
   east of the Forum, near the Caelian and Esquiline.
   ============================================================ */
window.RomeColosseum = (function () {
  'use strict';

  /* vertical elliptical wall band between heights y0..y1 (local) */
  function ring(parent, rx, rz, y0, y1, n, mat) {
    const pos = [], idx = [];
    for (let i = 0; i < n; i++) {
      const a0 = (i / n) * Math.PI * 2, a1 = ((i + 1) / n) * Math.PI * 2;
      const x0 = Math.cos(a0) * rx, z0 = Math.sin(a0) * rz;
      const x1 = Math.cos(a1) * rx, z1 = Math.sin(a1) * rz;
      pos.push(x0, y0, z0, x1, y0, z1, x1, y1, z1, x0, y1, z0);
      const a = i * 4;
      idx.push(a, a + 1, a + 3, a, a + 3, a + 2);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setIndex(idx);
    geo.computeVertexNormals();
    const m = new THREE.Mesh(geo, mat);
    m.castShadow = m.receiveShadow = true;
    parent.add(m);
  }

  /* a ring of piers + semicircular arches (facade arcade) */
  function arcades(parent, rx, rz, y, n, archH) {
    const M = ROME.M;
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2;
      const x = Math.cos(a) * rx, z = Math.sin(a) * rz;
      const ry = -a - Math.PI / 2;
      parent.add(ROME.box(1.6, archH, 1.6, M.stone, x, y, z, ry));
      const arc = new THREE.Mesh(new THREE.TorusGeometry(1.9, 0.5, 6, 10, Math.PI), M.travertine);
      arc.position.set(x, y + archH, z);
      arc.rotation.set(0, ry, 0);
      arc.castShadow = true;
      parent.add(arc);
    }
  }

  function buildColosseum(scene) {
    const M = ROME.M;
    const cx = 430, cz = 180;
    const gy = ROME.heightAt(cx, cz);
    const RX = 78, RZ = 56;
    const g = new THREE.Group();

    // Tier 1: ground arcade (tall, open colonnade)
    ring(g, RX, RZ, 0, 10, 64, M.travertine);
    ring(g, RX + 1.5, RZ + 1.5, 10, 12.5, 64, M.stone);        // entablature
    // Tier 2: semicircular arcades
    ring(g, RX - 1, RZ - 1, 12.5, 21, 64, M.travertine);
    ring(g, RX + 1, RZ + 1, 21, 23, 64, M.stone);
    // Tier 3: windowed Corinthian order
    ring(g, RX - 2.5, RZ - 2.5, 23, 31.5, 64, M.stone);
    ring(g, RX - 1, RZ - 1, 31.5, 33.5, 64, M.travertine);
    // Tier 4: attic (partly lost to history)
    ring(g, RX - 6, RZ - 6, 33.5, 38, 64, M.brick);

    // arcades on the two lower tiers
    arcades(g, RX + 0.2, RZ + 0.2, 0, 40, 9);
    arcades(g, RX + 0.8, RZ + 0.8, 13, 34, 7.5);

    // the four corner pendentive towers
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * Math.PI * 2 + Math.PI / 4;
      const x = Math.cos(a) * RX * 0.99, z = Math.sin(a) * RZ * 0.99;
      g.add(ROME.box(12, 46, 12, M.travertine, x, 0, z, -a));
    }

    // arena floor
    const arena = new THREE.Mesh(new THREE.CircleGeometry(52, 40), M.sand);
    arena.rotation.x = -Math.PI / 2;
    arena.scale.set(1.3, 1, 1);
    arena.position.y = 0.6;
    g.add(arena);

    // plinth hugging the terrain
    ring(g, RX + 3, RZ + 3, -3, 0.5, 64, M.stone);

    g.position.set(cx, gy, cz);
    scene.add(g);
  }

  return { buildColosseum: buildColosseum };
})();

/* ============================================================
   circuses.js — The chariot-racing circuses
   Circus Maximus — the vast long stadium in the valley
   between Palatine and Aventine (300 m track, central spina
   with the Egyptian obelisk and seven-loop bronze serpent)
   and the smaller Circus Flaminius in Campus Martius.
   ============================================================ */
window.RomeCircuses = (function () {
  'use strict';

  /* stepped spectator bank (three tiers of seating) */
  function bank(parent, x, z, len, ry, tiers) {
    const M = ROME.M;
    for (let t = 0; t < tiers; t++) {
      const w = 13, h = 3.4 + t * 0.6;
      const off = 0.5 + t * w;
      parent.add(ROME.box(len, h, w, M.travertine,
        x + Math.cos(ry + Math.PI / 2) * off, 0,
        z + Math.sin(ry + Math.PI / 2) * off, ry));
    }
  }

  function circusMaximus(scene) {
    const M = ROME.M;
    const cx = 210, cz = 460;         // valley between Palatine and Aventine
    const gy = ROME.heightAt(cx, cz);
    const LEN = 340, WID = 55;        // track: 340 m long, U-shaped, curved end to the W
    const g = new THREE.Group();

    // central spina with the obelisk of Pharaohs
    g.add(ROME.box(8, 4, LEN * 0.86, M.travertine, 0, 0, 0));
    g.add(ROME.box(3, 1, LEN * 0.86, M.stone, 0, 4, 0));
    // seven-loop bronze serpent at the spina end
    const serpent = new THREE.Mesh(new THREE.TorusGeometry(3, 0.5, 6, 20, Math.PI * 5), M.bronze);
    serpent.rotation.x = -Math.PI / 2;
    serpent.position.set(0, 5.2, LEN * 0.4);
    g.add(serpent);
    // the obelisk rides on its own module; mark position here
    ROME_OBELISK_SPINA = { x: cx, z: cz - LEN * 0.45 };

    // spectator banks along the straight sides
    bank(g, -WID - 16, 0, LEN, 0, 3);       // west bank
    bank(g,  WID + 16, 0, LEN, Math.PI, 3); // east bank (toward Palatine)

    // curved end to the west (toward the Forum)
    for (let i = 0; i <= 10; i++) {
      const a = -Math.PI / 2 + (Math.PI * i) / 10;
      const t = Math.round(i / 10);
      // three concentric arcs of seating blocks
      for (let ring = 0; ring < 3; ring++) {
        const rr = WID + 10 + ring * 13;
        const x = Math.cos(a) * rr, z = -LEN / 2 + 20 + Math.sin(a) * rr * 0.75;
        g.add(ROME.box(14, 3.4 + ring * 0.6, 14, M.travertine, x - WID - 4, 0, z, a + Math.PI / 2));
      }
    }
    // start gates (carceres) at the east end
    g.add(ROME.box(8, 9, WID * 2 + 20, M.stone, WID + 8, 0, LEN / 2 - 10));

    g.position.set(cx, gy, cz);
    scene.add(g);
  }

  function circusFlaminius(scene) {
    const M = ROME.M;
    const cx = -330, cz = -180;       // Campus Martius
    const gy = ROME.heightAt(cx, cz);
    const g = new THREE.Group();
    const LEN = 200, WID = 34;
    g.add(ROME.box(5, 3, LEN * 0.8, M.travertine, 0, 0, 0));           // spina
    g.add(ROME.box(LEN, 3.4, 10, M.travertine, 0, 0, -WID - 8));
    g.add(ROME.box(LEN, 3.8, 10, M.travertine, 0, 0, WID + 8));
    for (let i = 0; i <= 8; i++) {
      const a = Math.PI / 2 + (Math.PI * i) / 8;
      for (let ring = 0; ring < 2; ring++) {
        const rr = WID + 8 + ring * 12;
        g.add(ROME.box(12, 3.4 + ring * 0.6, 12, M.travertine,
          Math.cos(a) * rr, 0, LEN / 2 - 14 + Math.sin(a) * rr * 0.7, a));
      }
    }
    g.position.set(cx, gy, cz);
    scene.add(g);
  }

  function buildCircuses(scene) {
    circusMaximus(scene);
    circusFlaminius(scene);
  }

  return { buildCircuses: buildCircuses, SPINA: () => ROME_OBELISK_SPINA };
})();

/* ============================================================
   baths.js — The great public bath complexes (thermae)
   Baths of Caracalla (S-W) and Baths of Constantine (Quirinal):
   peristyle courtyard, main pool, domed caldarium/tepidarium
   fed by the aqueducts (hypocaust-heated).
   ============================================================ */
window.RomeBaths = (function () {
  'use strict';

  function domeRoom(g, x, z, r) {
    const M = ROME.M;
    g.add(ROME.cyl(r, r, r * 0.9, 24, M.brick, x, 0, z));
    const dome = new THREE.Mesh(new THREE.SphereGeometry(r, 24, 12, 0, Math.PI * 2, 0, Math.PI / 2), M.stone);
    dome.position.set(x, r * 0.9, z);
    dome.castShadow = true;
    g.add(dome);
  }

  function bathComplex(scene, x, z, scale, name) {
    const M = ROME.M;
    const gy = ROME.heightAt(x, z);
    const g = new THREE.Group();
    const s = scale;

    // outer walls
    g.add(ROME.box(90 * s, 8 * s, 6, M.brick, 0, 0, -45 * s));
    g.add(ROME.box(6, 8 * s, 90 * s, M.brick, -45 * s, 0, 0));
    g.add(ROME.box(6, 8 * s, 90 * s, M.brick, 45 * s, 0, 0));
    // entrance portico
    g.add(ROME.box(20 * s, 6 * s, 4, M.stone, 0, 0, 45 * s));
    g.add(ROME.box(24 * s, 1.5, 6, M.travertine, 0, 6 * s, 45 * s));

    // main pool (frigidarium)
    g.add(ROME.box(34 * s, 1.5, 22 * s, M.stone, 0, 0, 18 * s));
    const pool = new THREE.Mesh(new THREE.PlaneGeometry(30 * s, 18 * s), M.water);
    pool.rotation.x = -Math.PI / 2;
    pool.position.set(0, 1.6, 18 * s);
    g.add(pool);

    // domed halls (caldarium & tepidarium)
    domeRoom(g, -22 * s, -16 * s, 10 * s);
    domeRoom(g, 22 * s, -16 * s, 10 * s);
    domeRoom(g, 0, -24 * s, 14 * s);

    // peristyle colonnade
    for (let i = 0; i <= 6; i++) {
      const fx = -36 * s + (72 * s) * i / 6;
      g.add(ROME.cyl(0.5 * s, 0.6 * s, 6 * s, 10, M.marble, fx, 1.5, -2 * s));
      g.add(ROME.cyl(0.5 * s, 0.6 * s, 6 * s, 10, M.marble, fx, 1.5, 38 * s));
    }
    for (let i = 1; i < 6; i++) {
      const fz = -20 * s + (56 * s) * i / 6;
      g.add(ROME.cyl(0.5 * s, 0.6 * s, 6 * s, 10, M.marble, -36 * s, 1.5, fz));
      g.add(ROME.cyl(0.5 * s, 0.6 * s, 6 * s, 10, M.marble, 36 * s, 1.5, fz));
    }
    // a few trees in the gardens
    [[-30, 30], [30, 30], [-30, 2], [30, 2]].forEach(p => g.add(ROME.tree(p[0] * s, p[1] * s, 1.1)));

    g.position.set(x, gy, z);
    scene.add(g);
  }

  function buildBaths(scene) {
    bathComplex(scene, -260, 820, 1.4, 'Baths of Caracalla');
    bathComplex(scene, 120, -700, 0.8, 'Baths of Constantine');
  }

  return { buildBaths: buildBaths };
})();

