/* ============================================================
   villas.js — Country estates outside the Aurelian Walls
   Villa Urbana  — leisure retreat: atrium with impluvium,
               peristyle garden, triclinium, cubicula
   Villa Rustica — working estate: granaries, presses,
               stables and crop fields
   Villa Marittima — riverside villa on the Tiber with a pier
   ============================================================ */
window.RomeVillas = (function () {
  'use strict';

  /* residential wing: atrium house (pars urbana) */
  function parsUrbana(scene, x, z, ry, scale) {
    const M = ROME.M;
    const gy = ROME.heightAt(x, z);
    const s = scale || 1;
    const g = new THREE.Group();
    // four wings around the atrium
    g.add(ROME.box(24 * s, 5 * s, 7 * s, M.stone, 0, 0, -8 * s));
    g.add(ROME.box(24 * s, 5 * s, 7 * s, M.stone, 0, 0, 8 * s));
    g.add(ROME.box(7 * s, 5 * s, 16 * s, M.stone, -8.5 * s, 0, 0));
    g.add(ROME.box(7 * s, 5 * s, 16 * s, M.stone, 8.5 * s, 0, 0));
    // roofs
    for (const p of [[0, -8 * s, 25 * s, 8 * s], [0, 8 * s, 25 * s, 8 * s], [-8.5 * s, 0, 8 * s, 17 * s], [8.5 * s, 0, 8 * s, 17 * s]]) {
      g.add(ROME.box(p[2], 1, p[3], M.terracotta, p[0], 5 * s, p[1]));
    }
    // open atrium with impluvium (shallow basin catching rain)
    const impluvium = new THREE.Mesh(new THREE.PlaneGeometry(6 * s, 6 * s), M.water);
    impluvium.rotation.x = -Math.PI / 2;
    impluvium.position.y = 0.3;
    g.add(impluvium);
    // peristyle: colonnaded courtyard behind
    for (let i = 0; i <= 5; i++) {
      const cx = -15 * s + (30 * s) * i / 5;
      g.add(ROME.cyl(0.45 * s, 0.5 * s, 5.5 * s, 10, M.marble, cx, 0, 16 * s));
      g.add(ROME.cyl(0.45 * s, 0.5 * s, 5.5 * s, 10, M.marble, cx, 0, 30 * s));
      g.add(ROME.cyl(0.45 * s, 0.5 * s, 5.5 * s, 10, M.marble, -15 * s, 0, 16 * s + (14 * s) * i / 5));
      g.add(ROME.cyl(0.45 * s, 0.5 * s, 5.5 * s, 10, M.marble, 15 * s, 0, 16 * s + (14 * s) * i / 5));
    }
    // reflecting pool in the peristyle
    const pool = new THREE.Mesh(new THREE.PlaneGeometry(16 * s, 6 * s), M.water);
    pool.rotation.x = -Math.PI / 2;
    pool.position.set(0, 0.3, 23 * s);
    g.add(pool);
    // garden trees
    ltree(g, -8 * s, 20 * s, 1); ltree(g, 8 * s, 26 * s, 1); ltree(g, 0, 28 * s, 0.9);
    // triclinium opening to the garden (columns + low table)
    g.add(ROME.box(4 * s, 0.5, 2.5 * s, M.wood, 0, 0.6, 18 * s));

    g.position.set(x, gy, z);
    g.rotation.y = ry || 0;
    scene.add(g);
  }

  /* agricultural wing (pars rustica) */
  function parsRustica(scene, x, z, ry) {
    const M = ROME.M;
    const gy = ROME.heightAt(x, z);
    const g = new THREE.Group();
    // granary
    g.add(ROME.box(20, 6, 10, M.stone, 0, 0, -20));
    g.add(ROME.box(21, 0.8, 11, M.terracotta, 0, 6, -20));
    // wine/olive press house with vats
    g.add(ROME.box(12, 5, 8, M.brick, 16, 0, -14));
    for (let i = 0; i < 3; i++)
      g.add(ROME.cyl(1.4, 1.6, 4.4, 10, M.wood, 12 + i * 3, 0.2, -14));
    // stables
    g.add(ROME.box(10, 4.5, 16, M.wood, -16, 0, -16));
    // workers' quarters
    g.add(ROME.box(8, 4, 10, M.stone, -8, 0, -24));
    // grain field with crop rows
    const field = new THREE.Mesh(new THREE.PlaneGeometry(60, 40), new THREE.MeshLambertMaterial({ color: 0xa8a04a }));
    field.rotation.x = -Math.PI / 2;
    field.position.set(30, 0.2, 20);
    g.add(field);
    for (let i = 0; i < 8; i++) {
      const row = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.9, 38), M.green);
      row.position.set(6 + i * 7, 0.6, 20);
      g.add(row);
    }
    // vine rows
    for (let i = 0; i < 6; i++) {
      const row = new THREE.Mesh(new THREE.BoxGeometry(0.5, 1.1, 30), M.green);
      row.position.set(-20 - i * 5, 0.7, 14);
      g.add(row);
    }
    g.position.set(x, gy, z);
    g.rotation.y = ry || 0;
    scene.add(g);
  }

  function ltree(parent, x, z, s) {
    parent.add(ROME.cyl(0.3 * s, 0.4 * s, 2.2 * s, 6, ROME.M.wood, x, 0, z));
    const c = new THREE.Mesh(new THREE.ConeGeometry(1.4 * s, 5.5 * s, 8), ROME.M.green);
    c.position.set(x, 2.2 * s + 2.6 * s, z);
    c.castShadow = true;
    parent.add(c);
  }

  function buildVillas(scene) {
    // Villa Urbana — the great western countryside estate
    parsUrbana(scene, -750, -900, 0.6, 1.3);
    parsRustica(scene, -820, -760, 0.5);
    // Villa Rustica — along the Appia, south of the walls
    parsRustica(scene, 120, 1550, -0.3);
    parsUrbana(scene, -40, 1460, -0.4, 1);
    // Villa Marittima — on the Tiber, with a pier into the water
    const vx = ROME.riverXAt(1250) - 70, vz = 1250;
    parsUrbana(scene, vx, vz, -1.2, 0.9);
    const gy = ROME.heightAt(vx, vz);
    scene.add(ROME.box(4, 1.4, 22, ROME.M.wood, vx + 30, gy - 4, vz));
    // scattered olive trees in the villa countryside
    for (let i = 0; i < 20; i++) {
      const x = -1300 + Math.random() * 1100, z = -1500 + Math.random() * 500;
      if (Math.abs(x - ROME.riverXAt(z)) > 70) scene.add(ROME.tree(x, z, 1.4));
    }
    for (let i = 0; i < 12; i++) {
      const x = -400 + Math.random() * 900, z = 1350 + Math.random() * 400;
      if (Math.abs(x - ROME.riverXAt(z)) > 70) scene.add(ROME.tree(x, z, 1.4));
    }
  }

  return { buildVillas: buildVillas };
})();

/* ============================================================
   ui.js — Overlay UI (bottom-right corner)
   Mode badge, live position, and the mouse + keyboard
   control legend for walking and bird (flying) mode.
   ============================================================ */
window.UI = (function () {
  'use strict';

  let modeEl, posEl, promptEl;

  function el(tag, cls, html) {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (html !== undefined) e.innerHTML = html;
    return e;
  }

  function init() {
    /* ---- bottom-right control panel ---- */
    const hud = el('div', 'hud');
    hud.appendChild(el('div', 'hud-title', 'ROMA &middot; AETERNA'));
    hud.appendChild(el('div', 'hud-sub', 'Imperial Rome &middot; the Seven Hills'));
    modeEl = el('div', 'hud-mode walk', 'ON FOOT');
    hud.appendChild(modeEl);
    posEl = el('div', 'hud-pos', '');
    hud.appendChild(posEl);

    const help = el('div', 'hud-help');
    help.innerHTML =
      '<div class="hud-help-title">CONTROLS</div>' +
      '<table>' +
      '<tr><td class="k">Mouse</td><td>look around</td></tr>' +
      '<tr><td class="k">W A S D</td><td>walk / fly</td></tr>' +
      '<tr><td class="k">Shift</td><td>run (or fly fast)</td></tr>' +
      '<tr><td class="k">Space</td><td>jump &middot; in bird mode: rise</td></tr>' +
      '<tr><td class="k">C</td><td>in bird mode: descend</td></tr>' +
      '<tr><td class="k">B</td><td>bird mode (fly over the city)</td></tr>' +
      '<tr><td class="k">Esc</td><td>release the mouse</td></tr>' +
      '</table>';
    hud.appendChild(help);
    document.body.appendChild(hud);

    /* ---- crosshair ---- */
    document.body.appendChild(el('div', 'crosshair', '+'));

    /* ---- click-to-enter prompt ---- */
    promptEl = el('div', 'prompt');
    promptEl.innerHTML = '<div class="prompt-box">' +
      '<div class="prompt-title">ROMA AETERNA</div>' +
      '<div>Click to walk the streets of Imperial Rome</div>' +
      '<div class="prompt-sub">Press B anytime to rise like a bird above the city</div>' +
      '</div>';
    document.body.appendChild(promptEl);
  }

  function setMode(bird) {
    if (!modeEl) return;
    modeEl.textContent = bird ? 'BIRD FLIGHT' : 'ON FOOT';
    modeEl.className = 'hud-mode ' + (bird ? 'bird' : 'walk');
    document.body.classList.toggle('bird', bird);
  }

  function setPos(x, z) {
    if (posEl) posEl.textContent =
      'Pos ' + Math.round(x) + ' E, ' + Math.round(z) + ' S';
  }

  function setLocked(locked) {
    if (promptEl) promptEl.style.display = locked ? 'none' : 'flex';
  }

  return { init: init, setMode: setMode, setPos: setPos, setLocked: setLocked };
})();

/* Roma Aeterna — overlay UI styles */

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #000;
  font-family: Georgia, 'Times New Roman', serif;
  user-select: none;
}

#scene {
  display: block;
  width: 100%;
  height: 100%;
}

/* ---------- crosshair ---------- */
.crosshair {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  color: rgba(255, 245, 220, 0.75);
  font-size: 20px;
  pointer-events: none;
  text-shadow: 0 0 4px rgba(0, 0, 0, 0.8);
}

/* ---------- click prompt ---------- */
.prompt {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  z-index: 20;
}
.prompt-box {
  text-align: center;
  color: #f5ead0;
  background: rgba(22, 16, 8, 0.72);
  border: 1px solid #b08d3e;
  border-radius: 6px;
  padding: 26px 44px;
  box-shadow: 0 0 40px rgba(0, 0, 0, 0.6);
}
.prompt-title {
  font-size: 30px;
  letter-spacing: 6px;
  color: #d9b45c;
  margin-bottom: 10px;
}
.prompt-sub {
  margin-top: 8px;
  font-size: 13px;
  opacity: 0.75;
  font-style: italic;
}

/* ---------- bottom-right HUD panel ---------- */
.hud {
  position: fixed;
  right: 16px;
  bottom: 16px;
  width: 265px;
  z-index: 15;
  background: rgba(24, 18, 10, 0.78);
  border: 1px solid #b08d3e;
  border-radius: 6px;
  padding: 12px 14px 10px;
  color: #e9dcc0;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(3px);
}
.hud-title {
  font-size: 17px;
  letter-spacing: 3px;
  color: #d9b45c;
  text-align: center;
}
.hud-sub {
  font-size: 11px;
  text-align: center;
  opacity: 0.7;
  font-style: italic;
  margin-bottom: 8px;
}
.hud-mode {
  margin: 0 auto 6px;
  width: fit-content;
  padding: 3px 16px;
  border-radius: 12px;
  font-size: 12px;
  letter-spacing: 2px;
  border: 1px solid #7fae6a;
  color: #a8d99a;
  background: rgba(40, 66, 34, 0.5);
}
.hud-mode.bird {
  border-color: #6aa8d9;
  color: #a5cfee;
  background: rgba(30, 55, 84, 0.5);
}
.hud-pos {
  font-size: 11px;
  text-align: center;
  opacity: 0.65;
  margin-bottom: 8px;
}
.hud-help {
  border-top: 1px solid rgba(176, 141, 62, 0.5);
  padding-top: 8px;
}
.hud-help-title {
  font-size: 11px;
  letter-spacing: 2px;
  color: #d9b45c;
  text-align: center;
  margin-bottom: 6px;
}
.hud-help table {
  width: 100%;
  border-collapse: collapse;
  font-size: 11.5px;
}
.hud-help td {
  padding: 1.5px 4px;
  vertical-align: top;
}
.hud-help td.k {
  width: 88px;
  color: #f2d98c;
  white-space: nowrap;
  font-family: 'Courier New', monospace;
}

/* bird mode: subtle sky tint on the frame */
body.bird::after {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  box-shadow: inset 0 0 140px rgba(90, 160, 230, 0.25);
  z-index: 5;
}

/* ============================================================
   main.js — Scene, lighting, player (on foot + bird mode)
   ============================================================ */
(function () {
  'use strict';

  /* ---------- renderer / scene / camera ---------- */
  const canvas = document.getElementById('scene');
  const renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x9cc2e6);
  scene.fog = new THREE.Fog(0xc6d8e8, 350, 2600);

  const camera = new THREE.PerspectiveCamera(70, window.innerWidth / window.innerHeight, 0.1, 5000);

  /* ---------- lights ---------- */
  const hemi = new THREE.HemisphereLight(0xdfeaff, 0x6d6350, 0.85);
  scene.add(hemi);
  const sun = new THREE.DirectionalLight(0xfff0d0, 1.05);
  sun.position.set(700, 1100, 350);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  const S = 750;
  sun.shadow.camera.left = -S; sun.shadow.camera.right = S;
  sun.shadow.camera.top = S; sun.shadow.camera.bottom = -S;
  sun.shadow.camera.far = 3000;
  sun.shadow.bias = -0.0006;
  scene.add(sun);
  scene.add(sun.target);

  // a visible sun disc
  const sunDisc = new THREE.Mesh(
    new THREE.SphereGeometry(60, 16, 16),
    new THREE.MeshBasicMaterial({ color: 0xfff3c0 })
  );
  sunDisc.position.set(1400, 1900, 700);
  scene.add(sunDisc);

  /* ---------- build the world ---------- */
  ROME.buildTerrain(scene);
  ROME.buildRiver(scene);
  RomeRoads.buildRoads(scene);
  RomeWalls.buildWallsGates(scene);
  RomeTemples.buildTemples(scene);
  RomeColosseum.buildColosseum(scene);
  RomeCircuses.buildCircuses(scene);
  RomeBaths.buildBaths(scene);
  RomeBuildings.buildBuildings(scene);
  RomeObelisks.buildObelisks(scene);
  RomeColumns.buildColumns(scene);
  RomeArches.buildArches(scene);
  RomeAqueducts.buildAqueducts(scene);
  RomeFountains.buildFountains(scene);
  RomeVillas.buildVillas(scene);

  /* ---------- player ---------- */
  const EYE = 1.8;
  const player = {
    x: 30, z: 300,           // spawn on the Via Sacra, in the Forum
    y: 0, vy: 0,
    yaw: Math.PI,            // facing into the city
    pitch: 0,
    grounded: true,
    bird: false
  };
  player.y = ROME.heightAt(player.x, player.z) + EYE;

  const keys = {};
  let locked = false;

  document.addEventListener('keydown', e => {
    keys[e.code] = true;
    if (e.code === 'KeyB') {
      player.bird = !player.bird;
      UI.setMode(player.bird);
      if (player.bird) {
        // rise into the air
        player.vy = 8;
      } else {
        player.grounded = false;
      }
    }
    if (e.code === 'Space') e.preventDefault();
  });
  document.addEventListener('keyup', e => { keys[e.code] = false; });

  canvas.addEventListener('click', () => {
    if (!locked) canvas.requestPointerLock();
  });
  document.addEventListener('pointerlockchange', () => {
    locked = document.pointerLockElement === canvas;
    UI.setLocked(locked);
  });
  document.addEventListener('mousemove', e => {
    if (!locked) return;
    player.yaw += e.movementX * 0.0022;
    player.pitch -= e.movementY * 0.0022;
    player.pitch = Math.max(-1.5, Math.min(1.5, player.pitch));
  });

  /* ---------- main loop ---------- */
  const clock = new THREE.Clock();
  let hudTimer = 0;

  function update(dt) {
    const sprint = keys['ShiftLeft'] || keys['ShiftRight'];
    const fwd = (keys['KeyW'] || keys['ArrowUp'] ? 1 : 0) - (keys['KeyS'] || keys['ArrowDown'] ? 1 : 0);
    const strafe = (keys['KeyD'] || keys['ArrowRight'] ? 1 : 0) - (keys['KeyA'] || keys['ArrowLeft'] ? 1 : 0);

    if (player.bird) {
      /* --- bird mode: free flight over the city --- */
      const speed = sprint ? 90 : 45;
      const sin = Math.sin(player.yaw), cos = Math.cos(player.yaw);
      // forward = -z in view space
      player.x += (-sin * fwd + cos * strafe) * speed * dt;
      player.z += (-cos * fwd - sin * strafe) * speed * dt;
      const up = (keys['Space'] ? 1 : 0) - (keys['KeyC'] ? 1 : 0);
      player.y += up * speed * 0.6 * dt;
      const minY = ROME.heightAt(player.x, player.z) + 3;
      if (player.y < minY) { player.y = minY; }
      if (player.y > 600) player.y = 600;
    } else {
      /* --- on foot: walk with gravity, terrain collision --- */
      const speed = sprint ? 16 : 8;
      const sin = Math.sin(player.yaw), cos = Math.cos(player.yaw);
      const len = Math.hypot(fwd, strafe) || 1;
      player.x += (-sin * fwd / len + cos * strafe / len) * speed * dt;
      player.z += (-cos * fwd / len - sin * strafe / len) * speed * dt;
      const ground = ROME.heightAt(player.x, player.z) + EYE;
      // walking in the river: keep at water level
      const nearRiver = Math.abs(player.x - ROME.riverXAt(player.z)) < 34;
      const floorY = nearRiver ? Math.max(ground, ROME.RIVER_BED_Y + 1.2) : ground;
      if (keys['Space'] && player.grounded) { player.vy = 5.5; player.grounded = false; }
      player.vy -= 14 * dt;
      player.y += player.vy * dt;
      if (player.y <= floorY) { player.y = floorY; player.vy = 0; player.grounded = true; }
    }

    // keep the player in the world
    const BOUND = 1650;
    player.x = Math.max(-BOUND, Math.min(BOUND, player.x));
    player.z = Math.max(-BOUND, Math.min(BOUND, player.z));

    camera.position.set(player.x, player.y, player.z);
    camera.rotation.order = 'YXZ';
    camera.rotation.y = player.yaw;
    camera.rotation.x = player.pitch;

    // HUD (throttled)
    hudTimer += dt;
    if (hudTimer > 0.15) {
      hudTimer = 0;
      UI.setPos(player.x, player.z);
    }
  }

  function animate() {
    requestAnimationFrame(animate);
    const dt = Math.min(clock.getDelta(), 0.05);
    update(dt);
    renderer.render(scene, camera);
  }

  window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  });

  UI.init();
  UI.setPos(player.x, player.z);
  animate();
})();
